/* Momento site styles – minimal, accessible, and theme-aware */

:root {
  --bg: #0f1117;
  --panel-bg: #161b22;
  --text: #c9d1d9;
  --accent: #58a6ff;
  --accent-hover: #79c0ff;
  --border: #30363d;
  --success: #3fb950;
  --warning: #d29922;
  --error: #f85149;
  --muted: #8b949e;
  --copy-btn-bg: #21262d;
  --copy-btn-hover: #30363d;
}

/* Reset and base */
*,
*::before,
*::after {
  box-sizing: border-box;
}
html {
  line-height: 1.5;
  -webkit-text-size-adjust: 100%;
}
body {
  margin: 0;
  font-family: -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, Helvetica, Arial, sans-serif;
  background: var(--bg);
  color: var(--text);
  display: flex;
  flex-direction: column;
  min-height: 100vh;
}

/* Navigation */
.nav {
  background: var(--panel-bg);
  border-bottom: 1px solid var(--border);
  padding: .5rem 1rem;
}
.nav nav {
  display: flex;
  flex-wrap: wrap;
  gap: .75rem;
  align-items: center;
  max-width: 100%;
}
.nav a {
  color: var(--accent);
  text-decoration: none;
  font-weight: 500;
}
.nav a:hover,
.nav a:focus {
  color: var(--accent-hover);
  outline: none;
}
.nav p {
  margin: 0 0 0 auto;
  font-size: .9rem;
  color: var(--muted);
}

/* Main layout */
main {
  flex: 1;
  max-width: 960px;
  margin: 0 auto;
  padding: 1rem;
}

/* Panels */
.panel {
  background: var(--panel-bg);
  border: 1px solid var(--border);
  border-radius: 6px;
  padding: 1rem;
  margin-bottom: 1rem;
}
.panel h2,
.panel h3 {
  margin-top: 0;
  color: var(--accent);
}

/* Lists */
ul {
  list-style: none;
  padding: 0;
  margin: 0;
}
li {
  margin-bottom: .5rem;
}

/* Copy button */
.copy-button {
  background: var(--copy-btn-bg);
  border: 1px solid var(--border);
  color: var(--accent);
  padding: .2rem .45rem;
  margin-left: .4rem;
  border-radius: 4px;
  cursor: pointer;
  font-size: .85rem;
  transition: background .2s, color .2s;
}
.copy-button:hover,
.copy-button:focus {
  background: var(--copy-btn-hover);
  color: var(--accent-hover);
  outline: none;
}

/* Countdown */
.countdown-container {
  display: flex;
  align-items: center;
  gap: .75rem;
}
.countdown {
  font-family: monospace;
  font-size: 1.4rem;
  color: var(--accent);
}
.progress-bar {
  flex: 1;
  height: 8px;
  background: var(--border);
  border-radius: 4px;
  overflow: hidden;
}
.progress-fill {
  height: 100%;
  background: var(--accent);
  transition: width .3s, background .3s;
}

/* Relative time */
.relative-time {
  font-size: .85rem;
  color: var(--muted);
  margin-left: .4rem;
}

/* Footer */
.footer {
  background: var(--panel-bg);
  border-top: 1px solid var(--border);
  padding: .5rem 1rem;
}
.footer nav {
  display: flex;
  flex-wrap: wrap;
  gap: .75rem;
}
.footer p {
  margin: 0 0 0 auto;
  font-size: .9rem;
  color: var(--muted);
}

/* Utility: visually hidden */
.visually-hidden {
  position: absolute;
  width: 1px;
  height: 1px;
  padding: 0;
  margin: -1px;
  overflow: hidden;
  clip: rect(0, 0, 0, 0);
  white-space: nowrap;
  border: 0;
}

/* Wake state classes */
.wake-past {
  color: var(--muted);
}
.wake-current {
  color: var(--accent);
  font-weight: bold;
}
.wake-next {
  color: var(--warning);
}

/* Focus styles */
a:focus,
button:focus {
  outline: 2px solid var(--accent);
  outline-offset: 2px;
}

/* Reduced motion */
@media (prefers-reduced-motion: reduce) {
  * {
    animation: none !important;
    transition: none !important;
  }
}
